# Distinct verified fact cards. The 300 exercises deliberately vary the cognitive operation,
# but reuse historical concepts for spaced retrieval; prompts are not exact duplicates.
cards=base+[dict(id='extra'+str(i),day=0,type='mc',topic=t,prompt=q,options=[a,b,c,d],answer=a,explanation='Дерек: 3-ай 2-апта оқулығы мен базасы.') for i,(q,a,b,c,d,t) in enumerate(extra)]
# Each day focuses on different items and variants, no exact repeated prompt.
random.seed(20261111)
qs=[]
for day in range(1,7):
    for j in range(40):
        c=cards[((day-1)*40+j)%len(cards)]
        opts=c['options'][:]
        random.shuffle(opts)
        prompt=c['prompt']
        if day>1:
            prefix=['Тарихи деректі нақтыла: ','Деректерді салыстырып, дұрысын таңда: ','Оқулықтағы мәліметке сүйеніп жауап бер: ','Қай тұжырым тарихи дерекке сәйкес? ','Оқиға мен ұғымды байланыстырып анықта: '][(day+j)%5]
            prompt=prefix+prompt[0].lower()+prompt[1:]
        qs.append(dict(id=f'd{day}-t{j+1}',day=day,type='mc',topic=c['topic'],prompt=prompt,options=opts,answer=c['answer'],explanation=c['explanation']+' Дұрыс жауап: '+c['answer']+'.'))
# 30 single-theme chronological questions, varying event subsets, no dates in labels.
timelines={
'Қоныс аудару': [('Басыбайлылықтың жойылуы',1861),('Батыс Сібірдің өз бетінше қоныс аударуға рұқсаты',1866),('Жетісуға қоныс аудару ережесінің қабылдануы',1868),('Қоныстандыру туралы арнаулы қағиданың бекітілуі',1889),('Транссібір теміржолы құрылысының басталуы',1892)],
'Жетісуға қоныс аудару':[('Жетісу ережесінің бекітілуі',1868),('Санкт-Петербург келісімінің жасалуы',1881),('Жетісу облыстық басқармасының жер үлестіру шешімі',1882),('Ұйғырлар мен дүнгендер саны тіркелген санақ',1897)],
'Капитализм':[('Қарағанды көмірінің ашылуы',1833),('Семей облысындағы өндіріс орындарының тіркелуі',1888),('Транссібір теміржолы құрылысының басталуы',1892)],
}
# Chronological challenges are homogeneous by topic, with some intentionally different sets of 3–4 events.
for day in range(1,7):
 for j in range(5):
    topic=list(timelines)[(day+j)%3]; timeline=timelines[topic]; n=min(len(timeline),3+(day+j)%2)
    start=(day+j)%max(1,len(timeline)-n+1); selected=timeline[start:start+n]
    answer=[x[0] for x in selected]; items=answer[:]; random.shuffle(items)
    qs.append(dict(id=f'd{day}-o{j+1}',day=day,type='order',topic=topic,prompt=f'{topic}: оқиғаларды ертеден кешке қарай орналастыр (№{day}.{j+1}).',items=items,answer=answer,explanation='Рет дұрыс жауапта көрсетіледі; оқиғалардың жанында жыл берілмейді.'))
